#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> adj(N + 1);
    for (int i = 0; i < M; ++i) {
        int x, y;
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    vector<char> visited(N + 1, false);
    for (int start = 1; start <= N; ++start) {
        if (visited[start]) continue;

        vector<int> component;
        stack<int> st;
        st.push(start);
        visited[start] = true;

        long long degreeSum = 0;
        while (!st.empty()) {
            int v = st.top();
            st.pop();
            component.push_back(v);
            degreeSum += adj[v].size();

            for (int u : adj[v]) {
                if (!visited[u]) {
                    visited[u] = true;
                    st.push(u);
                }
            }
        }

        long long k = component.size();
        if (degreeSum < k * (k - 1)) {
            int v = -1;
            for (int u : component) {
                if ((long long)adj[u].size() < k - 1) {
                    v = u;
                    break;
                }
            }

            vector<char> isNeighbor(N + 1, false);
            for (int u : adj[v]) isNeighbor[u] = true;

            for (int u : component) {
                if (u != v && !isNeighbor[u]) {
                    cout << v << ' ' << u << '\n';
                    return 0;
                }
            }
        }
    }

    cout << -1 << '\n';
    return 0;
}
